import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import { viteSingleFile } from 'vite-plugin-singlefile'

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [react(), viteSingleFile()],
})

import React, { useState } from 'react';
import Dashboard from './components/Dashboard';
import ExchangeRateConfig from './components/Settings/ExchangeRateConfig';
import { useExchangeRate } from './hooks/useExchangeRate';
import { settlementApi } from './services/api';
import SmartInput from './components/SmartInput';

// Mock data (s? l?y t? state th?c t? sau này khi n?i Agent)
const initialItems: Array<{id: number, date: string, descZh: string, descVi: string, amountRmb: number}> = [];

function App() {
  const { rate, setRate } = useExchangeRate(3800);
  const [employeeName, setEmployeeName] = useState('Nguy?n Quý Luong');
  const [items, setItems] = useState(initialItems);
  const [isConfigOpen, setIsConfigOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // Tính toán l?i m?ng data v?i t? giá m?i (Live-update) và s?p x?p theo ngày
  const computedItems = items
    .map(item => ({
      ...item,
      amountVnd: Math.round(item.amountRmb * rate)
    }))
    .sort((a, b) => {
      // Parse DD/MM for comparison
      const parseDate = (d: string) => {
        const parts = d.split('/');
        if (parts.length === 2) {
          return parseInt(parts[1], 10) * 100 + parseInt(parts[0], 10); // MM * 100 + DD
        }
        return 0; // Fallback for invalid dates
      };
      // S?p x?p gi?m d?n (M?i nh?t lên d?u)
      return parseDate(b.date) - parseDate(a.date);
    });

  const handleSaveSettlement = async () => {
    try {
      setIsSaving(true);
      const res = await settlementApi.saveSettlement(employeeName, rate, computedItems);
      alert('Ðã t?o thành công Báo cáo Quy?t toán!\nLink Google Sheets:\n' + (res as any).sheetUrl);
    } catch (error) {
      alert('L?i khi luu d? li?u!');
    } finally {
      setIsSaving(false);
    }
  };

  const handleAIResult = (aiItems: any[]) => {
    // Map d? li?u t? AI v? d?ng SettlementItem, t?o ID ng?u nhiên
    const newItems = aiItems.map(item => ({
      id: Math.random(),
      date: item.date || new Date().toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit' }),
      descZh: item.descZh || '',
      descVi: item.descVi || '',
      // N?u AI tr? v? VND thì convert ngu?c ra RMB (b?ng cách chia rate) d? d?ng nh?t luu tr? g?c là RMB
      // Ho?c n?u nó tr? RMB thì l?y luôn
      amountRmb: item.currency === 'VND' ? (item.amount / rate) : (item.amount || 0)
    }));
    setItems([...items, ...newItems]);
  };

  const handleDelete = (id: number) => {
    setItems(items.filter(item => item.id !== id));
  };

  const handleEdit = (id: number, updated: any) => {
    setItems(items.map(item => {
      if (item.id === id) {
        // N?u s?a giá VND, c?p nh?t l?i RMB tuong ?ng
        const newRmb = updated.amountVnd !== undefined && updated.amountVnd !== item.amountVnd * rate
          ? updated.amountVnd / rate 
          : item.amountRmb;

        return { ...item, ...updated, amountRmb: newRmb };
      }
      return item;
    }));
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col font-sans">
      <header className="bg-primary text-white p-4 shadow-md sticky top-0 z-10 flex justify-between items-center">
        <h1 className="text-xl font-bold tracking-tight">ZRG Settlement</h1>
        <button 
          onClick={() => setIsConfigOpen(true)}
          className="text-sm bg-indigo-800/50 hover:bg-indigo-800 px-3 py-1 rounded-full font-medium transition-colors"
        >
          T? giá: {rate.toLocaleString('vi-VN')}
        </button>
      </header>

      <main className="flex-1 overflow-y-auto pb-24">
        <Dashboard 
          items={computedItems} 
          onSave={handleSaveSettlement} 
          isSaving={isSaving} 
          onDelete={handleDelete}
          onEdit={handleEdit}
        />
        <SmartInput onResult={handleAIResult} />
      </main>

      <ExchangeRateConfig 
        isOpen={isConfigOpen} 
        onClose={() => setIsConfigOpen(false)} 
        currentRate={rate}
        currentEmployee={employeeName}
        onSave={(newRate, newEmployee) => {
          setRate(newRate);
          setEmployeeName(newEmployee);
        }}
      />
    </div>
  )
}

export default App;

import React, { useState, useEffect } from 'react';
import { geminiService } from '../../services/geminiService';
import { Loader2 } from 'lucide-react';

type SettlementItem = {
  id: number;
  date: string;
  descZh: string;
  descVi: string;
  amountRmb: number;
  amountVnd: number;
};

interface EditItemModalProps {
  isOpen: boolean;
  item: SettlementItem | null;
  onClose: () => void;
  onSave: (id: number, updated: Partial<SettlementItem>) => void;
}

export default function EditItemModal({ isOpen, item, onClose, onSave }: EditItemModalProps) {
  const [formData, setFormData] = useState({
    date: '',
    descVi: '',
    descZh: '',
    amountVnd: 0
  });

  const [isTranslating, setIsTranslating] = useState(false);
  const [changedField, setChangedField] = useState<'vi' | 'zh' | null>(null);

  useEffect(() => {
    if (item) {
      setFormData({
        date: item.date,
        descVi: item.descVi,
        descZh: item.descZh,
        amountVnd: item.amountVnd
      });
      setChangedField(null);
    }
  }, [item]);

  const handleBlurVi = async () => {
    if (changedField === 'vi' && formData.descVi) {
      setIsTranslating(true);
      try {
        const translated = await geminiService.translateText(formData.descVi, 'zh');
        if (translated) {
          setFormData(prev => ({ ...prev, descZh: translated }));
        }
      } finally {
        setIsTranslating(false);
        setChangedField(null);
      }
    }
  };

  const handleBlurZh = async () => {
    if (changedField === 'zh' && formData.descZh) {
      setIsTranslating(true);
      try {
        const translated = await geminiService.translateText(formData.descZh, 'vi');
        if (translated) {
          setFormData(prev => ({ ...prev, descVi: translated }));
        }
      } finally {
        setIsTranslating(false);
        setChangedField(null);
      }
    }
  };

  if (!isOpen || !item) return null;

  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl p-5 w-full max-w-md shadow-xl">
        <div className="flex justify-between items-center mb-4">
          <h3 className="text-lg font-bold text-gray-900">Ch?nh s?a kho?n chi</h3>
          {isTranslating && <Loader2 className="w-5 h-5 text-primary animate-spin" />}
        </div>

        <div className="space-y-4">
          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1">Ngày tháng (DD/MM)</label>
            <input 
              type="text" 
              value={formData.date}
              onChange={e => setFormData({...formData, date: e.target.value})}
              className="w-full border border-gray-300 rounded-lg p-2 focus:ring-2 focus:ring-primary focus:outline-none"
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1">N?i dung (Ti?ng Vi?t)</label>
            <input 
              type="text" 
              value={formData.descVi}
              onChange={e => {
                setFormData({...formData, descVi: e.target.value});
                setChangedField('vi');
              }}
              onBlur={handleBlurVi}
              className="w-full border border-gray-300 rounded-lg p-2 focus:ring-2 focus:ring-primary focus:outline-none"
              placeholder="Nh?p ti?ng Vi?t..."
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1">N?i dung (Ti?ng Trung)</label>
            <input 
              type="text" 
              value={formData.descZh}
              onChange={e => {
                setFormData({...formData, descZh: e.target.value});
                setChangedField('zh');
              }}
              onBlur={handleBlurZh}
              className="w-full border border-gray-300 rounded-lg p-2 focus:ring-2 focus:ring-primary focus:outline-none"
              placeholder="Nh?p ti?ng Trung..."
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1">S? ti?n (VND)</label>
            <input 
              type="text" 
              inputMode="numeric"
              value={formData.amountVnd ? formData.amountVnd.toLocaleString('en-US') : ''}
              onChange={e => {
                const val = e.target.value.replace(/[^0-9]/g, '');
                setFormData({...formData, amountVnd: val ? parseInt(val, 10) : 0});
              }}
              className="w-full border border-gray-300 rounded-lg p-2 focus:ring-2 focus:ring-primary focus:outline-none"
            />
          </div>
        </div>

        <div className="flex gap-3 mt-6">
          <button 
            onClick={onClose}
            disabled={isTranslating}
            className="flex-1 bg-gray-100 text-gray-700 py-2.5 rounded-xl font-medium disabled:opacity-50"
          >
            H?y b?
          </button>
          <button 
            onClick={() => onSave(item.id, formData)}
            disabled={isTranslating}
            className="flex-1 bg-primary text-white py-2.5 rounded-xl font-medium disabled:opacity-50"
          >
            Luu thay d?i
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import SmartInput from '../SmartInput';
import EditItemModal from './EditItemModal';

type SettlementItem = {
  id: number;
  date: string;
  descZh: string;
  descVi: string;
  amountRmb: number;
  amountVnd: number;
};

interface DashboardProps {
  items: SettlementItem[];
  onSave: () => void;
  isSaving: boolean;
  onDelete: (id: number) => void;
  onEdit: (id: number, updated: Partial<SettlementItem>) => void;
}

import * as XLSX from 'xlsx';

export default function Dashboard({ items, onSave, isSaving, onDelete, onEdit }: DashboardProps) {
  const [editingItem, setEditingItem] = useState<SettlementItem | null>(null);

  // Tính t?ng t? d?ng
  const totalVnd = items.reduce((acc, curr) => acc + curr.amountVnd, 0);

  const handleSaveEdit = (id: number, updated: Partial<SettlementItem>) => {
    onEdit(id, updated);
    setEditingItem(null);
  };

  const handleExportExcel = () => {
    if (items.length === 0) return;

    const header = ['STT', 'Ngày', 'N?i dung (Ti?ng Trung)', 'N?i dung (Ti?ng Vi?t)', 'S? lu?ng', 'Ðon giá RMB', 'Thành ti?n VND'];

    const rows = items.map((item, index) => [
      index + 1,
      item.date,
      item.descZh,
      item.descVi,
      1,
      item.amountRmb,
      item.amountVnd
    ]);

    rows.push(['', '', '', '', '', 'T?NG C?NG:', totalVnd]);

    const worksheet = XLSX.utils.aoa_to_sheet([header, ...rows]);

    // Auto-size columns loosely
    const wscols = [
      { wch: 5 }, { wch: 10 }, { wch: 30 }, { wch: 30 }, { wch: 10 }, { wch: 15 }, { wch: 15 }
    ];
    worksheet['!cols'] = wscols;

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "QuyetToan");

    const today = new Date();
    const dateStr = `${today.getDate()}_${today.getMonth() + 1}`;
    XLSX.writeFile(workbook, `Quyet_Toan_ZRG_${dateStr}.xlsx`);
  };

  return (
    <div className="p-4 flex flex-col h-full relative">
      <div className="flex-1 space-y-4">
        <h2 className="text-gray-500 text-sm font-semibold uppercase tracking-wider mb-2">Kho?n chi g?n dây</h2>

        {items.map((item) => (
          <div key={item.id} className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100 flex flex-col transition-all group">
            <div className="flex items-start justify-between">
              <div className="flex-1 pr-2">
                <div className="flex items-center gap-2 mb-1">
                  <span className="text-xs font-medium bg-gray-100 text-gray-600 px-2 py-0.5 rounded-md">{item.date}</span>
                  <p className="text-sm font-medium text-gray-900 leading-tight">{item.descVi}</p>
                </div>
                <p className="text-xs text-gray-400 mt-1">{item.descZh}</p>
              </div>
              <div className="text-right whitespace-nowrap">
                <p className="text-sm font-bold text-gray-900">{item.amountVnd.toLocaleString('vi-VN')} ?</p>
                <p className="text-xs text-gray-400">¥{item.amountRmb.toFixed(2)}</p>
              </div>
            </div>

            <div className="flex justify-end gap-2 mt-3 pt-3 border-t border-gray-50">
              <button
                onClick={() => setEditingItem(item)}
                className="text-xs font-medium text-indigo-600 bg-indigo-50 px-3 py-1.5 rounded-lg flex items-center gap-1 hover:bg-indigo-100"
              >
                <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                S?a
              </button>
              <button
                onClick={() => {
                  if (window.confirm('B?n có ch?c mu?n xóa kho?n chi này?')) onDelete(item.id);
                }}
                className="text-xs font-medium text-red-600 bg-red-50 px-3 py-1.5 rounded-lg flex items-center gap-1 hover:bg-red-100"
              >
                <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                Xóa
              </button>
            </div>
          </div>
        ))}

        {items.length === 0 && (
          <div className="text-center p-8 text-gray-400">
            Chua có kho?n chi nào. Vui lòng b?m Camera ho?c Mic d? b?t d?u.
          </div>
        )}
      </div>

      <SmartInput />

      <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 p-4 pb-safe flex items-center justify-between shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-10 gap-3">
        <div className="flex-shrink-0">
          <p className="text-xs text-gray-500 font-medium">T?ng ti?n (VND)</p>
          <p className="text-xl font-bold text-primary">{totalVnd.toLocaleString('vi-VN')} ?</p>
        </div>
        <div className="flex gap-2 flex-1 justify-end">
          <button
            onClick={handleExportExcel}
            disabled={items.length === 0}
            className="flex-1 max-w-[120px] bg-blue-500 text-white hover:bg-blue-600 shadow-md shadow-blue-200 px-3 py-3 rounded-xl font-semibold text-sm disabled:opacity-50 transition-colors whitespace-nowrap"
          >
            Xu?t Excel
          </button>
          <button
            onClick={onSave}
            disabled={isSaving || items.length === 0}
            className="flex-1 max-w-[140px] bg-emerald-500 text-white hover:bg-emerald-600 shadow-md shadow-emerald-200 px-3 py-3 rounded-xl font-semibold text-sm disabled:opacity-50 transition-colors whitespace-nowrap"
          >
            {isSaving ? 'Ðang luu...' : 'Xu?t Báo cáo'}
          </button>
        </div>
      </div>

      <EditItemModal
        isOpen={!!editingItem}
        item={editingItem}
        onClose={() => setEditingItem(null)}
        onSave={handleSaveEdit}
      />
    </div>
  );
}

import React, { useState } from 'react';

interface ExchangeRateConfigProps {
  isOpen: boolean;
  onClose: () => void;
  currentRate: number;
  currentEmployee: string;
  onSave: (newRate: number, employeeName: string) => void;
}

export default function ExchangeRateConfig({ isOpen, onClose, currentRate, currentEmployee, onSave }: ExchangeRateConfigProps) {
  const [tempRate, setTempRate] = useState(currentRate.toString());
  const [tempName, setTempName] = useState(currentEmployee);

  if (!isOpen) return null;

  const handleSave = () => {
    const parsed = parseInt(tempRate.replace(/,/g, ''), 10);
    if (!isNaN(parsed) && parsed > 0 && tempName.trim() !== '') {
      onSave(parsed, tempName.trim());
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/50 p-4 pb-safe">
      <div className="bg-white w-full max-w-sm rounded-3xl p-6 shadow-xl animate-in slide-in-from-bottom-10 sm:slide-in-from-bottom-0 sm:zoom-in-95">
        <h3 className="text-lg font-bold text-gray-900 mb-4">C?u hình T? giá</h3>

        <div className="mb-4">
          <label className="block text-sm font-medium text-gray-700 mb-2">Tên nhân viên (Ngu?i quy?t toán)</label>
          <input 
            type="text" 
            className="w-full text-lg font-bold text-gray-900 border-b-2 border-gray-200 focus:border-primary focus:outline-none py-2 transition-colors placeholder:font-normal placeholder:text-gray-300"
            placeholder="Ví d?: Nguy?n Quý Luong"
            value={tempName}
            onChange={(e) => setTempName(e.target.value)}
          />
        </div>

        <div className="mb-6">
          <label className="block text-sm font-medium text-gray-700 mb-2">T? giá hi?n t?i (VND/RMB)</label>
          <input 
            type="number" 
            className="w-full text-2xl font-bold text-primary border-b-2 border-gray-200 focus:border-primary focus:outline-none py-2 transition-colors"
            value={tempRate}
            onChange={(e) => setTempRate(e.target.value)}
            pattern="[0-9]*"
            inputMode="numeric"
          />
        </div>

        <div className="flex gap-3">
          <button 
            onClick={onClose}
            className="flex-1 py-3 bg-gray-100 text-gray-700 rounded-xl font-semibold hover:bg-gray-200 transition-colors"
          >
            H?y
          </button>
          <button 
            onClick={handleSave}
            className="flex-1 py-3 btn-primary font-semibold"
          >
            Luu
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { useRef, useState } from 'react';
import { Mic, Camera, Loader2 } from 'lucide-react';
import { geminiService } from '../../services/geminiService';

interface SmartInputProps {
  onResult: (items: any[]) => void;
}

export default function SmartInput({ onResult }: SmartInputProps) {
  const [isRecording, setIsRecording] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [showCameraMenu, setShowCameraMenu] = useState(false);
  const cameraInputRef = useRef<HTMLInputElement>(null);
  const galleryInputRef = useRef<HTMLInputElement>(null);
  const audioInputRef = useRef<HTMLInputElement>(null);

  const handleMicClick = () => {
    audioInputRef.current?.click();
  };

  const handleAudioChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    try {
      setIsProcessing(true);
      const file = files[0];

      const base64Audio = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = error => reject(error);
      });

      const results = await geminiService.analyzeVoiceAudio(base64Audio, file.type);
      if (results && results.length > 0) {
        onResult(results);
      }
    } catch (error) {
      console.error(error);
      alert('L?i khi x? lý âm thanh: ' + (error instanceof Error ? error.message : JSON.stringify(error)));
    } finally {
      setIsProcessing(false);
      if (audioInputRef.current) audioInputRef.current.value = '';
    }
  };

  const handleCameraClick = () => {
    setShowCameraMenu(!showCameraMenu);
  };

  const triggerCamera = () => {
    setShowCameraMenu(false);
    cameraInputRef.current?.click();
  };

  const triggerGallery = () => {
    setShowCameraMenu(false);
    galleryInputRef.current?.click();
  };

  const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    try {
      setIsProcessing(true);
      const allResults: any[] = [];

      for (let i = 0; i < files.length; i++) {
        const file = files[i];

        const base64Image = await new Promise<string>((resolve, reject) => {
          const reader = new FileReader();
          reader.readAsDataURL(file);
          reader.onload = () => resolve(reader.result as string);
          reader.onerror = error => reject(error);
        });

        const results = await geminiService.analyzeReceipt(base64Image, file.type);
        if (results && results.length > 0) {
          allResults.push(...results);
        }
      }

      if (allResults.length > 0) {
        onResult(allResults);
      }
    } catch (error) {
      console.error(error);
      alert('L?i khi x? lý ?nh b?ng AI: ' + (error instanceof Error ? error.message : JSON.stringify(error)));
    } finally {
      setIsProcessing(false);
      if (cameraInputRef.current) cameraInputRef.current.value = '';
      if (galleryInputRef.current) galleryInputRef.current.value = '';
    }
  };

  // Close menu when clicking outside
  React.useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      if (!target.closest('.camera-menu-container')) {
        setShowCameraMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <div className="fixed bottom-24 right-4 flex flex-col gap-3 z-20">
      {/* Input cho Ch?p ?nh tr?c ti?p */}
      <input 
        type="file" 
        accept="image/*" 
        capture="environment"
        ref={cameraInputRef}
        onChange={handleFileChange}
        className="hidden"
      />

      {/* Input cho Ch?n t? thu vi?n */}
      <input 
        type="file" 
        accept="image/*" 
        multiple
        ref={galleryInputRef}
        onChange={handleFileChange}
        className="hidden"
      />

      {/* Input ?n d? ghi âm */}
      <input 
        type="file" 
        accept="audio/*" 
        capture="microphone"
        ref={audioInputRef}
        onChange={handleAudioChange}
        className="hidden"
      />

