export const geminiService = {
  /**
   * Phân tích ?nh hóa don (Base64)
   * @param base64Image ?nh d?ng base64
   * @param mimeType Ð?nh d?ng ?nh (vd: image/jpeg)
   */
  async analyzeReceipt(base64Image: string, mimeType: string) {
    try {
      // S? d?ng model Flash 2.5 m?i nh?t do 1.5 dã deprecated
      const model = genAI.getGenerativeModel({ model: "gemini-2.5-flash" });

      // Lu?c b? ph?n header c?a base64 (n?u có, vd: data:image/jpeg;base64,...)
      const base64Data = base64Image.split(',')[1] || base64Image;

      const imagePart = {
        inlineData: {
          data: base64Data,
          mimeType
        },
      };

      const result = await model.generateContent([SYSTEM_PROMPT, imagePart]);
      const response = await result.response;
      let text = response.text();

      // Làm s?ch text d? parse JSON (Lo?i b? markdown ```json ... ```)
      text = text.replace(/```json/g, '').replace(/```/g, '').trim();

      const parsedData = JSON.parse(text);
      return Array.isArray(parsedData) ? parsedData : [parsedData];
    } catch (error) {
      console.error("L?i khi x? lý ?nh qua Gemini:", error);
      throw error;
    }
  },

  /**
   * Phân tích van b?n thô (gi?ng nói STT)
   * @param voiceText Van b?n do Speech-to-Text nh?n di?n du?c
   */
  async analyzeVoiceText(voiceText: string) {
    try {
      const model = genAI.getGenerativeModel({ model: "gemini-2.5-flash" });

      const prompt = `${SYSTEM_PROMPT}\n\nD? li?u d?u vào là l?i nói c?a nhân viên:\n"${voiceText}"\nHãy l?c b? t? lóng, chu?n hóa s? ti?n và tr? v? JSON h?p l?.`;

      const result = await model.generateContent([prompt]);
      const response = await result.response;
      let text = response.text();

      // Làm s?ch text d? parse JSON (Lo?i b? markdown ```json ... ```)
      text = text.replace(/```json/g, '').replace(/```/g, '').trim();

      const parsedData = JSON.parse(text);
      return Array.isArray(parsedData) ? parsedData : [parsedData];
    } catch (error) {
      console.error("L?i khi x? lý gi?ng nói qua Gemini:", error);
      throw error;
    }
  },

  /**
   * Phân tích âm thanh (file ghi âm)
   * @param base64Audio Âm thanh d?ng base64
   * @param mimeType Ð?nh d?ng file âm thanh
   */
  async analyzeVoiceAudio(base64Audio: string, mimeType: string) {
    try {
      const model = genAI.getGenerativeModel({ model: "gemini-2.5-flash" });

      const prompt = `${SYSTEM_PROMPT}\n\nD? li?u d?u vào là 1 do?n âm thanh ghi âm l?i nói c?a nhân viên.\nHãy nghe, l?c b? t? lóng, ng?p ng?ng, chu?n hóa s? ti?n và tr? v? JSON h?p l?. Ð?ng tr? v? b?t k? text nào khác ngoài m?ng JSON.`;

      const base64Data = base64Audio.split(',')[1] || base64Audio;
      // Tránh l?i mimeType l? t? các di?n tho?i khác nhau, Gemini h? tr? t?t các d?nh d?ng thông thu?ng
      const safeMimeType = mimeType || 'audio/mp3';

      const audioPart = {
        inlineData: {
          data: base64Data,
          mimeType: safeMimeType
        },
      };

      const result = await model.generateContent([prompt, audioPart]);
      const response = await result.response;
      let text = response.text();

      text = text.replace(/```json/g, '').replace(/```/g, '').trim();
      const parsedData = JSON.parse(text);
      return Array.isArray(parsedData) ? parsedData : [parsedData];
    } catch (error) {
      console.error("L?i khi x? lý file âm thanh qua Gemini:", error);
      throw error;
    }
  },

  /**
   * D?ch thu?t t? d?ng song ng?
   * @param text Van b?n c?n d?ch
