   */
  async translateText(text: string, toLang: 'vi' | 'zh') {
    try {
      const model = genAI.getGenerativeModel({ model: "gemini-2.5-flash" });
      const targetLang = toLang === 'vi' ? 'Ti?ng Vi?t' : 'Ti?ng Trung Gi?n Th?';
      const prompt = `D?ch do?n van b?n sau sang ${targetLang}. Ch? tr? v? k?t qu? d?ch, không gi?i thích gì thêm.\n\nVan b?n: "${text}"`;

      const result = await model.generateContent([prompt]);
      const response = await result.response;
      return response.text().trim();
